import{_ as t,c as d,o as a,V as r}from"./chunks/framework.tJhZUYt7.js";const _=JSON.parse('{"title":"五、操作运算符","description":"","frontmatter":{},"headers":[],"relativePath":"rear/java/Java基础语法/操作运算符.md","filePath":"rear/java/Java基础语法/操作运算符.md","lastUpdated":1719821588000}'),e={name:"rear/java/Java基础语法/操作运算符.md"},h=r('<h1 id="五、操作运算符" tabindex="-1">五、操作运算符 <a class="header-anchor" href="#五、操作运算符" aria-label="Permalink to &quot;五、操作运算符&quot;">​</a></h1><h2 id="一、算术运算符" tabindex="-1">一、算术运算符 <a class="header-anchor" href="#一、算术运算符" aria-label="Permalink to &quot;一、算术运算符&quot;">​</a></h2><table><thead><tr><th>运算符</th><th>说明</th></tr></thead><tbody><tr><td>+</td><td>加法，相加运算符两侧的值</td></tr><tr><td>-</td><td>减法，左操作数减去右操作数</td></tr><tr><td>*</td><td>乘法，相乘运算符两侧的值</td></tr><tr><td>/</td><td>除法，做操作数除以右操作数</td></tr><tr><td>%</td><td>取模，左操作数除以右操作数的余数</td></tr></tbody></table><h2 id="二、自增自减运算符" tabindex="-1">二、自增自减运算符 <a class="header-anchor" href="#二、自增自减运算符" aria-label="Permalink to &quot;二、自增自减运算符&quot;">​</a></h2><table><thead><tr><th>运算符</th><th>说明</th></tr></thead><tbody><tr><td>++</td><td>自增，操作数的值增加1</td></tr><tr><td>--</td><td>自减，操作数的值减少1</td></tr></tbody></table><h2 id="三、赋值运算符" tabindex="-1">三、赋值运算符 <a class="header-anchor" href="#三、赋值运算符" aria-label="Permalink to &quot;三、赋值运算符&quot;">​</a></h2><table><thead><tr><th>运算符</th><th>说明</th></tr></thead><tbody><tr><td>=</td><td>简单的赋值运算符，将右操作数的值赋给左操作数</td></tr><tr><td>+=</td><td>加和赋值运算符，它把左操作数和右操作数相加赋值给左操作数</td></tr><tr><td>-=</td><td>减和赋值运算符，它把左操作数和右操作数相减赋值给左操作数</td></tr><tr><td>*=</td><td>乘和赋值运算符，它把左操作数和右操作数相乘赋值给左操作数</td></tr><tr><td>/=</td><td>除和赋值运算符，它把左操作数和右操作数相除赋值给左操作数</td></tr><tr><td>%=</td><td>取模和赋值运算符，它把左操作数和右操作数取模后赋值给左操作数</td></tr><tr><td>&lt;&lt;=</td><td>左移位赋值运算符</td></tr><tr><td>&gt;&gt;=</td><td>右移位赋值运算符</td></tr><tr><td>&amp;=</td><td>按位与赋值运算符</td></tr><tr><td>^=</td><td>按位异或赋值运算符</td></tr><tr><td>!=</td><td>按位或赋值运算符</td></tr></tbody></table><h2 id="四、比较运算符" tabindex="-1">四、比较运算符 <a class="header-anchor" href="#四、比较运算符" aria-label="Permalink to &quot;四、比较运算符&quot;">​</a></h2><table><thead><tr><th>运算符</th><th>说明</th></tr></thead><tbody><tr><td>==</td><td>检查两个操作数的值是否相等，如果相等则条件为真</td></tr><tr><td>!=</td><td>检查两个操作数的值是否不相等，如果不相等则条件为真</td></tr><tr><td>&gt;</td><td>检查左操作数的值是否大于右操作数的值，如果是，那么条件为真</td></tr><tr><td>&lt;</td><td>检查左操作数的值是否小于右操作数的值，如果是，那么条件为真</td></tr><tr><td>&gt;=</td><td>检查左操作数的值是否大于或等于右操作数的值，如果是，那么条件为真</td></tr><tr><td>&lt;=</td><td>检查左操作数的值是否小于或等于右操作数的值，如果是，那么条件为真</td></tr></tbody></table><h2 id="五、逻辑运算符" tabindex="-1">五、逻辑运算符 <a class="header-anchor" href="#五、逻辑运算符" aria-label="Permalink to &quot;五、逻辑运算符&quot;">​</a></h2><table><thead><tr><th>运算符</th><th>作用</th><th>说明</th></tr></thead><tbody><tr><td>&amp;&amp;</td><td>逻辑与</td><td>两边都为真，结果才为真</td></tr><tr><td>||</td><td>逻辑或</td><td>两边都为假，结果才为假</td></tr><tr><td>!</td><td>逻辑非</td><td>取反</td></tr></tbody></table><h2 id="六、三元运算符" tabindex="-1">六、三元运算符 <a class="header-anchor" href="#六、三元运算符" aria-label="Permalink to &quot;六、三元运算符&quot;">​</a></h2><p>使用规则：</p><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">b</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果result为true，则值为a；如果result为false，则值为b</p><h2 id="七、位运算符" tabindex="-1">七、位运算符 <a class="header-anchor" href="#七、位运算符" aria-label="Permalink to &quot;七、位运算符&quot;">​</a></h2><table><thead><tr><th>运算符</th><th>说明</th></tr></thead><tbody><tr><td>&amp;</td><td>按位与运算符，如果相对应位都是1，则结果为1，否则为0</td></tr><tr><td>|</td><td>按位或运算符，如果相对应位都是0，则结果为0，否则为1</td></tr><tr><td>^</td><td>按位异或运算符，如果相对应位值相同，则结果为0，否则为1</td></tr><tr><td>~</td><td>按位补运算符，翻转操作数的每一位，即0变成1，1变成0</td></tr><tr><td>&lt;&lt;</td><td>按位左移运算符，左操作数按位左移右操作数所指定的位数</td></tr><tr><td>&gt;&gt;</td><td>按位右移运算符，左操作数按位右移右操作数所指定的位数</td></tr><tr><td>&gt;&gt;&gt;</td><td>按位右移补零操作符，左操作数的值按右操作数所指定的位数右移，移动得到的空位以0填充</td></tr></tbody></table><h2 id="八、运算符优先级" tabindex="-1">八、运算符优先级 <a class="header-anchor" href="#八、运算符优先级" aria-label="Permalink to &quot;八、运算符优先级&quot;">​</a></h2><table><thead><tr><th>优先级</th><th>运算符</th><th>方向</th></tr></thead><tbody><tr><td>1</td><td>[].()（方法调用）</td><td>从左向右</td></tr><tr><td>2</td><td>!、~、++、--、+（一元运算）、-（一元运算）</td><td>从右向左</td></tr><tr><td>3</td><td>*、/、%</td><td>从左向右</td></tr><tr><td>4</td><td>+、-</td><td>从左向右</td></tr><tr><td>5</td><td>&lt;&lt;、&gt;&gt;、&gt;&gt;&gt;</td><td>从左向右</td></tr><tr><td>6</td><td>&lt;、&lt;=、&gt;、&gt;=、instanceof</td><td>从左向右</td></tr><tr><td>7</td><td>==、!=</td><td>从左向右</td></tr><tr><td>8</td><td>&amp;</td><td>从左向右</td></tr><tr><td>9</td><td>^</td><td>从左向右</td></tr><tr><td>10</td><td>|</td><td>从左向右</td></tr><tr><td>11</td><td>&amp;&amp;</td><td>从左向右</td></tr><tr><td>12</td><td>||</td><td>从左向右</td></tr><tr><td>13</td><td>?:</td><td>从右向左</td></tr><tr><td>14</td><td>=</td><td>从右向左</td></tr></tbody></table>',19),l=[h];function s(i,o,n,b,c,p){return a(),d("div",null,l)}const m=t(e,[["render",s]]);export{_ as __pageData,m as default};
